// @FIGURE_CODE_BEGIN
var figHost = document.getElementById('container');
var gfxDraw = SVG().addTo(figHost).size('100%', '100%');

var COL = { blue: '#1f9fd8', fill: '#c2e1f2', ink: '#1a1a1a', accent: '#e07b00', red: '#cc2f26' };
var PW = 500, PH = 560, CX = 250, CY = 265, RX = 205, RY = 196, HRX = 76, HRY = 86;
var SERIF = 'Georgia,"Times New Roman",serif';

var figState = { stage: 1, hx: 330, hy: 360, hs: 1, walk: false, step: 0 };
var walkers = [];
var dragCtx = null;
var panelOff = { a: [0, 0], b: [0, 0] };

/* ── geometry ─────────────────────────────────────────────── */
function angDiff(a, b) { var d = Math.abs(a - b) % (2 * Math.PI); return d > Math.PI ? 2 * Math.PI - d : d; }

function outerPt(t) {
  var g = Math.exp(-Math.pow(angDiff(t, Math.PI + 0.49), 2) / (2 * 0.30 * 0.30));
  var r = 1 + 0.07 * Math.cos(t) + 0.05 * Math.sin(t) - 0.55 * g;
  return [CX + RX * r * Math.cos(t), CY - RY * r * Math.sin(t)];
}
function holePt(t) {
  var g = Math.exp(-Math.pow(angDiff(t, Math.PI + 0.25), 2) / (2 * 0.33 * 0.33));
  var r = (1 + 0.06 * Math.sin(t) + 0.04 * Math.cos(t) - 0.44 * g) * figState.hs;
  return [figState.hx + HRX * r * Math.cos(t), figState.hy - HRY * r * Math.sin(t)];
}
function samplePts(fn, n) { var a = [], i; for (i = 0; i < n; i++) a.push(fn(i / n * 2 * Math.PI)); return a; }
var OUTER = samplePts(outerPt, 300);
function holePts() { return samplePts(holePt, 300); }

function pathStr(p) {
  var s = 'M' + p[0][0].toFixed(2) + ' ' + p[0][1].toFixed(2), i;
  for (i = 1; i < p.length; i++) s += 'L' + p[i][0].toFixed(2) + ' ' + p[i][1].toFixed(2);
  return s + 'Z';
}
function xCross(p, y) {
  var out = [], i, j, a, b;
  for (i = 0; i < p.length; i++) {
    j = (i + 1) % p.length; a = p[i]; b = p[j];
    if ((a[1] <= y) !== (b[1] <= y)) out.push(a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1]));
  }
  out.sort(function (m, n) { return m - n; });
  return out;
}
function cutY() { return figState.hy - 30; }
function anchorsAt(y, hp) {
  var xo = xCross(OUTER, y), xh = xCross(hp, y), i;
  if (xo.length < 2 || xh.length < 2) return null;
  var hl = xh[0], hr = xh[xh.length - 1], ol = null, or_ = null;
  for (i = 0; i < xo.length; i++) {
    if (xo[i] < hl - 4 && (ol === null || xo[i] > ol)) ol = xo[i];
