// @FIGURE_CODE_BEGIN
var figHost = document.getElementById('container');
var gfxDraw = SVG().addTo(figHost).size('100%', '100%');

var COL = { blue: '#1f9fd8', fill: '#c2e1f2', ink: '#1a1a1a', accent: '#e07b00', red: '#cc2f26' };
var PW = 500, PH = 560, CX = 250, CY = 265, RX = 205, RY = 196, HRX = 76, HRY = 86;
var SERIF = 'Georgia,"Times New Roman",serif';

var figState = { stage: 1, hx: 330, hy: 360, hs: 1, walk: false, step: 0 };
var walkers = [];
var dragCtx = null;
var panelOff = { a: [0, 0], b: [0, 0] };

/* ── geometry ─────────────────────────────────────────────── */
function angDiff(a, b) { var d = Math.abs(a - b) % (2 * Math.PI); return d > Math.PI ? 2 * Math.PI - d : d; }

function outerPt(t) {
  var g = Math.exp(-Math.pow(angDiff(t, Math.PI + 0.49), 2) / (2 * 0.30 * 0.30));
  var r = 1 + 0.07 * Math.cos(t) + 0.05 * Math.sin(t) - 0.55 * g;
  return [CX + RX * r * Math.cos(t), CY - RY * r * Math.sin(t)];
}
function holePt(t) {
  var g = Math.exp(-Math.pow(angDiff(t, Math.PI + 0.25), 2) / (2 * 0.33 * 0.33));
  var r = (1 + 0.06 * Math.sin(t) + 0.04 * Math.cos(t) - 0.44 * g) * figState.hs;
  return [figState.hx + HRX * r * Math.cos(t), figState.hy - HRY * r * Math.sin(t)];
}
function samplePts(fn, n) { var a = [], i; for (i = 0; i < n; i++) a.push(fn(i / n * 2 * Math.PI)); return a; }
var OUTER = samplePts(outerPt, 300);
function holePts() { return samplePts(holePt, 300); }

function pathStr(p) {
  var s = 'M' + p[0][0].toFixed(2) + ' ' + p[0][1].toFixed(2), i;
  for (i = 1; i < p.length; i++) s += 'L' + p[i][0].toFixed(2) + ' ' + p[i][1].toFixed(2);
  return s + 'Z';
}
function xCross(p, y) {
  var out = [], i, j, a, b;
  for (i = 0; i < p.length; i++) {
    j = (i + 1) % p.length; a = p[i]; b = p[j];
    if ((a[1] <= y) !== (b[1] <= y)) out.push(a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1]));
  }
  out.sort(function (m, n) { return m - n; });
  return out;
}
function cutY() { return figState.hy - 30; }
function anchorsAt(y, hp) {
  var xo = xCross(OUTER, y), xh = xCross(hp, y), i;
  if (xo.length < 2 || xh.length < 2) return null;
  var hl = xh[0], hr = xh[xh.length - 1], ol = null, or_ = null;
  for (i = 0; i < xo.length; i++) {
    if (xo[i] < hl - 4 && (ol === null || xo[i] > ol)) ol = xo[i];
    if (xo[i] > hr + 4 && (or_ === null || xo[i] < or_)) or_ = xo[i];
  }
  if (ol === null || or_ === null) return null;
  return { ol: ol, hl: hl, hr: hr, or: or_ };
}
function inPoly(x, y, poly) {
  var inside = false, i, j, xi, yi, xj, yj;
  for (i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    xi = poly[i][0]; yi = poly[i][1]; xj = poly[j][0]; yj = poly[j][1];
    if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) inside = !inside;
  }
  return inside;
}
function validHole() {
  var hp = holePts(), i, p;
  for (i = 0; i < hp.length; i += 3) {
    p = [figState.hx + (hp[i][0] - figState.hx) * 1.14, figState.hy + (hp[i][1] - figState.hy) * 1.14];
    if (!inPoly(p[0], p[1], OUTER)) return false;
  }
  var yc = cutY();
  var a = anchorsAt(yc, hp), u = anchorsAt(yc - 7, hp), l = anchorsAt(yc + 7, hp);
  if (!a || !u || !l) return false;
  if (a.hl - a.ol < 26 || a.or - a.hr < 26) return false;
  return true;
}
function tryHole(x, y, s) {
  var ox = figState.hx, oy = figState.hy, os = figState.hs;
  figState.hx = x; figState.hy = y; figState.hs = s;
  if (!validHole()) { figState.hx = ox; figState.hy = oy; figState.hs = os; }
  render();
}

/* ── small drawing helpers ────────────────────────────────── */
function triPts(x, y, dx, dy, len, wid) {
  var m = Math.sqrt(dx * dx + dy * dy) || 1, ux = dx / m, uy = dy / m, px = -uy, py = ux;
  var tx = x + ux * len * 0.5, ty = y + uy * len * 0.5, bx = x - ux * len * 0.5, by = y - uy * len * 0.5;
  return [[tx, ty], [bx + px * wid / 2, by + py * wid / 2], [bx - px * wid / 2, by - py * wid / 2]];
}
function curveArrow(t, fn, tt, sign, len, wid, color) {
  var p = fn(tt), p1 = fn(tt + 0.02 * sign), p0 = fn(tt - 0.02 * sign);
  return t.polygon(triPts(p[0], p[1], p1[0] - p0[0], p1[1] - p0[1], len, wid))
    .fill(color).stroke({ color: color, width: 2, linejoin: 'round' });
}
function txt(parent, x, y, str, size, anchor, color, italic, halo) {
  var t = parent.plain(str);
  t.attr({
    x: x, y: y, 'text-anchor': anchor || 'middle', 'font-size': size,
    'font-family': SERIF, 'font-style': italic ? 'italic' : 'normal'
  });
  t.fill(color || COL.ink);
  if (halo) t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}
function mathSub(parent, x, y, main, sub, size, color) {
  var g = parent.group();
  txt(g, x, y, main, size, 'middle', color, true, true);
  txt(g, x + size * 0.40, y + size * 0.18, sub, size * 0.64, 'start', color, true, true);
  return g;
}
function interact(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

/* ── cut drawing ──────────────────────────────────────────── */
function cutLine(g, x1, x2, y, right, op) {
  g.line(x1, y, x2, y).stroke({ color: COL.ink, width: 2.6 }).opacity(op);
  var xm = x1 + (x2 - x1) * 0.55;
  g.polygon(triPts(xm, y, right ? 1 : -1, 0, 16, 11)).fill(COL.ink).opacity(op);
}
function cutHit(g, xa, xb, y) {
  var r = g.rect(Math.abs(xb - xa) + 10, 34).move(Math.min(xa, xb) - 5, y - 17).fill('#fff').opacity(0);
  interact(r, 'Cut: walked → for R′ and ← for R″',
    'A cut is walked twice',
    'Each cut segment belongs to the boundary of both R′ and R″, but the two pieces traverse it in opposite directions. The two line integrals are exact negatives, so together they contribute nothing.');
}
function drawCutBands(g, yc, hp, cancelled) {
  var d = 7, op = cancelled ? 0.45 : 1;
  var up = anchorsAt(yc - d, hp), lo = anchorsAt(yc + d, hp);
  if (up) { cutLine(g, up.ol, up.hl, yc - d, true, op); cutLine(g, up.hr, up.or, yc - d, true, op); }
  if (lo) { cutLine(g, lo.hl, lo.ol, yc + d, false, op); cutLine(g, lo.or, lo.hr, yc + d, false, op); }
  if (up && lo) {
    if (cancelled) {
      [[(up.ol + up.hl) / 2, 0], [(up.hr + up.or) / 2, 0]].forEach(function (m) {
        var x = m[0], s = 11;
        g.line(x - s, yc - s, x + s, yc + s).stroke({ color: COL.red, width: 3.4, linecap: 'round' });
        g.line(x - s, yc + s, x + s, yc - s).stroke({ color: COL.red, width: 3.4, linecap: 'round' });
      });
    }
    cutHit(g, up.ol, up.hl, yc); cutHit(g, up.hr, up.or, yc);
  }
}
function drawCutEdges(g, yc, hp, right) {
  var a = anchorsAt(yc, hp);
  if (!a) return;
  if (right) { cutLine(g, a.ol, a.hl, yc, true, 1); cutLine(g, a.hr, a.or, yc, true, 1); }
  else { cutLine(g, a.hl, a.ol, yc, false, 1); cutLine(g, a.or, a.hr, yc, false, 1); }
}

/* ── body (region + boundary + arrows) ────────────────────── */
function drawBody(t, hp, opt) {
  var reg = t.path(pathStr(OUTER) + ' ' + pathStr(hp)).attr({ 'fill-rule': 'evenodd' }).fill(COL.fill).stroke('none');
  interact(reg, 'R — the shaded, doubly connected region', 'The region R',
    'R lies between the outer curve C₁ and the hole boundary C₂. It is not simply connected, so Green\'s Theorem cannot be applied to it directly.');

  var hole = t.path(pathStr(hp)).fill('#ffffff').stroke('none');
  hole.css('cursor', 'move');
  hole.on('mousemove', function (e) { showTooltip('Drag me — the cuts follow', e); });
  hole.on('mouseleave', function () { hideTooltip(); });
  hole.on('pointerdown', function (e) {
    e.preventDefault();
    var p = toLocal(e, opt.ox, opt.oy);
    dragCtx = { ox: opt.ox, oy: opt.oy, dx: figState.hx - p[0], dy: figState.hy - p[1] };
  });

  var oc = t.path(pathStr(OUTER)).fill('none').stroke({ color: COL.blue, width: 8, linejoin: 'round' });
  interact(oc, 'C₁ — outer boundary, counterclockwise', 'Outer curve C₁',
    'Travelling counterclockwise along C₁ keeps the shaded region on your left. That is the positive orientation for the outer boundary.');
  var hc = t.path(pathStr(hp)).fill('none').stroke({ color: COL.blue, width: 8, linejoin: 'round' });
  interact(hc, 'C₂ — hole boundary, clockwise', 'Hole boundary C₂',
    'The hole boundary must be traversed clockwise. It looks "backwards", but it obeys exactly the same rule: the region R stays on your left as you walk.');

  curveArrow(t, outerPt, 2.25, 1, 36, 28, COL.blue);
  curveArrow(t, outerPt, -0.80, 1, 36, 28, COL.blue);
  curveArrow(t, holePt, 1.15, -1, 30, 24, COL.blue);
  curveArrow(t, holePt, -1.55, -1, 30, 24, COL.blue);
  curveArrow(t, holePt, -2.45, -1, 30, 24, COL.blue);

  if (figState.walk) addWalkers(t);
}
function addWalkers(t) {
  var g = t.group();
  [{ f: outerPt, s: 1, t0: 0.4 }, { f: holePt, s: -1, t0: 1.6 }].forEach(function (w) {
    var line = g.line(0, 0, 0, 0).stroke({ color: COL.accent, width: 4 });
    var nrm = g.polygon([[0, 0], [1, 0], [1, 1]]).fill(COL.accent);
    var dot = g.circle(15).fill('#ffffff').stroke({ color: COL.accent, width: 4 }).center(-99, -99);
    walkers.push({ f: w.f, s: w.s, t0: w.t0, dot: dot, line: line, nrm: nrm });
  });
}

/* ── panels ───────────────────────────────────────────────── */
function drawPanel(ox, oy, opt) {
  var g = gfxDraw.group().translate(ox, oy);
  if (opt.dim) g.opacity(0.30);
  var hp = holePts(), yc = cutY(), st = opt.stage, sep = 20;
  opt.ox = ox; opt.oy = oy;

  if (st === 2) {
    var wrapU = g.group().translate(0, -sep);
    var inU = wrapU.group();
    var cpU = gfxDraw.clip(); cpU.add(gfxDraw.rect(PW + 240, yc + 500).move(-120, -500));
    inU.clipWith(cpU);
    drawBody(inU, hp, opt);
    var lnU = wrapU.group(); drawCutEdges(lnU, yc, hp, true);
    mathSub(wrapU, figState.hx - 14, figState.hy - 104, 'C', '2', 38);
    txt(wrapU, 198, 195, 'R\u2032', 40, 'middle', COL.ink, true, true);

    var wrapL = g.group().translate(0, sep);
    var inL = wrapL.group();
    var cpL = gfxDraw.clip(); cpL.add(gfxDraw.rect(PW + 240, 900).move(-120, yc));
    inL.clipWith(cpL);
    drawBody(inL, hp, opt);
    var lnL = wrapL.group(); drawCutEdges(lnL, yc, hp, false);
    txt(wrapL, 228, 472, 'R\u2033', 40, 'middle', COL.ink, true, true);
  } else {
    drawBody(g, hp, opt);
    if (st >= 1) drawCutBands(g, yc, hp, st === 3);
    mathSub(g, figState.hx - 14, figState.hy - 104, 'C', '2', 38);
    if (st === 0) {
      txt(g, 202, 195, 'R', 40, 'middle', COL.ink, true, true);
    } else {
      txt(g, 198, 195, 'R\u2032', 40, 'middle', COL.ink, true, true);
      txt(g, 228, 472, 'R\u2033', 40, 'middle', COL.ink, true, true);
    }
  }

  mathSub(g, 252, 48, 'C', '1', 40);
  txt(g, 250, 543, opt.caption, 40, 'middle', COL.ink, true, false);

  if (opt.which === 'a' && figState.step === 1) {
    txt(g, 250, 502, 'positive orientation: region always on the left', 19, 'middle', COL.accent, false, true);
  }
  if (opt.which === 'b' && figState.step === 4) {
    txt(g, 250, 502, 'cut contributions cancel in pairs', 19, 'middle', COL.red, false, true);
  }
}

/* ── render / layout ──────────────────────────────────────── */
function render() {
  gfxDraw.clear();
  walkers = [];
  var w = figHost.clientWidth || 800, h = figHost.clientHeight || 600;
  var side = (w / Math.max(1, h)) > 1.05;
  var a, b;
  if (side) { gfxDraw.viewbox(0, 0, 1050, 600); a = [15, 20]; b = [545, 20]; }
  else { gfxDraw.viewbox(0, 0, 520, 1170); a = [10, 10]; b = [10, 595]; }
  panelOff.a = a; panelOff.b = b;
  var focus = STEPS[figState.step] ? STEPS[figState.step].focus : null;
  drawPanel(a[0], a[1], { stage: 0, caption: '(a)', which: 'a', dim: focus === 'b' });
  drawPanel(b[0], b[1], { stage: figState.stage, caption: '(b)', which: 'b', dim: focus === 'a' });
}

function toLocal(evt, ox, oy) {
  var pt = gfxDraw.node.createSVGPoint();
  pt.x = evt.clientX; pt.y = evt.clientY;
  var p = pt.matrixTransform(gfxDraw.node.getScreenCTM().inverse());
  return [p.x - ox, p.y - oy];
}
document.addEventListener('pointermove', function (e) {
  if (!dragCtx) return;
  var p = toLocal(e, dragCtx.ox, dragCtx.oy);
  tryHole(p[0] + dragCtx.dx, p[1] + dragCtx.dy, figState.hs);
});
document.addEventListener('pointerup', function () { dragCtx = null; });

/* ── animation ────────────────────────────────────────────── */
var uPhase = 0;
function tick() {
  if (figState.walk && walkers.length) {
    uPhase += 0.0022; if (uPhase > 1) uPhase -= 1;
    for (var i = 0; i < walkers.length; i++) {
      var wk = walkers[i], tt = wk.t0 + wk.s * uPhase * 2 * Math.PI;
      var p = wk.f(tt), p1 = wk.f(tt + 0.02 * wk.s), p0 = wk.f(tt - 0.02 * wk.s);
      var dx = p1[0] - p0[0], dy = p1[1] - p0[1], m = Math.sqrt(dx * dx + dy * dy) || 1;
      var ux = dx / m, uy = dy / m, lx = uy, ly = -ux;
      wk.dot.center(p[0], p[1]);
      wk.line.plot(p[0], p[1], p[0] + lx * 24, p[1] + ly * 24);
      wk.nrm.plot(triPts(p[0] + lx * 31, p[1] + ly * 31, lx, ly, 14, 12));
    }
  }
  requestAnimationFrame(tick);
}

/* ── controls ─────────────────────────────────────────────── */
function setStage(i) {
  figState.stage = i;
  updateStageButtons();
  render();
}
function updateStageButtons() {
  for (var i = 0; i < 4; i++) {
    var el = document.getElementById('stageBtn' + i);
    if (el) el.classList.toggle('active', i === figState.stage);
  }
}
function toggle_traverseArrow(on) { figState.walk = !!on; render(); }
function update_holeSize(v) { tryHole(figState.hx, figState.hy, v); }
function resetHole() {
  figState.hx = 330; figState.hy = 360; figState.hs = 1;
  document.getElementById('holeSizeInput').value = 1;
  document.getElementById('holeSizeVal').value = '1.00';
  render();
}

/* ── demo steps ───────────────────────────────────────────── */
var STEPS = [
  {
    t: 'A doubly connected region', stage: 1, walk: false, focus: null,
    n: 'The shaded region R lies between an outer curve C₁ and the boundary C₂ of a hole. Because of the hole, R is not simply connected, so Green\'s Theorem does not apply directly.'
  },
  {
    t: 'Positive orientation means region on your left', stage: 1, walk: true, focus: 'a',
    n: 'Walk the boundary: on C₁ you travel counterclockwise, but on C₂ you must travel clockwise. In both cases the shaded region stays on your left (orange arrow) — that is the single rule behind the two apparently opposite directions.'
  },
  {
    t: 'Introduce two cuts', stage: 1, walk: false, focus: 'b',
    n: 'Two horizontal cuts are drawn from the outer curve to the hole. Each cut is a single segment, but it will be traversed once in each direction.'
  },
  {
    t: 'Two simply connected pieces', stage: 2, walk: false, focus: 'b',
    n: 'The cuts split R into an upper piece R′ and a lower piece R″. Each has no hole, so Green\'s Theorem applies to each separately; their boundaries include the cut segments.'
  },
  {
    t: 'The cuts cancel', stage: 3, walk: false, focus: 'b',
    n: 'Along each cut, R′ is traversed rightward while R″ is traversed leftward. The two line integrals are negatives of each other and cancel, leaving exactly the integral over C₁ counterclockwise plus C₂ clockwise.'
