];
function applyStep(i) {
  figState.step = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[figState.step];
  figState.stage = s.stage;
  figState.walk = s.walk;
  var cb = document.getElementById('traverseArrowInput');
  if (cb) cb.checked = s.walk;
  document.getElementById('demoNarration').innerHTML = '<b>' + s.t + '.</b> ' + s.n;
  document.getElementById('stepLabel').textContent = (figState.step + 1) + ' / ' + STEPS.length;
  updateStageButtons();
  render();
}
function nextStep() { applyStep(figState.step + 1); }
function prevStep() { applyStep(figState.step - 1); }

/* ── boot ─────────────────────────────────────────────────── */
document.addEventListener('fig-resize', function () { render(); });
applyStep(0);
requestAnimationFrame(tick);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Green's Theorem extends to a multiply connected region by cutting it into simply connected pieces: the cuts are traversed twice in opposite directions so their contributions cancel, leaving the outer boundary counterclockwise and the inner boundary clockwise.
KEY INSIGHT (what students should walk away understanding): The 'backwards' clockwise orientation of the hole is forced by one rule — keep the region on your left — and the cuts that prove it disappear because every cut is walked once in each direction.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
