<label>Hole size: <output id="holeSizeVal">1.00</output><input id="holeSizeInput" type="range" min="0.70" max="1.25" step="0.02" value="1" oninput="document.getElementById('holeSizeVal').value=(+this.value).toFixed(2);update_holeSize(+this.value)"></label>
