    'Each cut segment belongs to the boundary of both R′ and R″, but the two pieces traverse it in opposite directions. The two line integrals are exact negatives, so together they contribute nothing.');
}
function drawCutBands(g, yc, hp, cancelled) {
  var d = 9, op = cancelled ? 0.40 : 1;
  var up = anchorsAt(yc - d, hp), lo = anchorsAt(yc + d, hp);
  if (up) { cutLine(g, up.ol, up.hl, yc - d, true, op); cutLine(g, up.hr, up.or, yc - d, true, op); }
  if (lo) { cutLine(g, lo.hl, lo.ol, yc + d, false, op); cutLine(g, lo.or, lo.hr, yc + d, false, op); }
  if (up && lo) {
    if (cancelled) {
      [(up.ol + up.hl) / 2, (up.hr + up.or) / 2].forEach(function (x) {
        var s = 13;
        g.line(x - s, yc - s, x + s, yc + s).stroke({ color: COL.red, width: 4, linecap: 'round' });
        g.line(x - s, yc + s, x + s, yc - s).stroke({ color: COL.red, width: 4, linecap: 'round' });
      });
    }
    cutHit(g, up.ol, up.hl, yc); cutHit(g, up.hr, up.or, yc);
  }
}
function drawCutEdges(g, yc, hp, right) {
  var a = anchorsAt(yc, hp);
  if (!a) return;
  if (right) { cutLine(g, a.ol, a.hl, yc, true, 1); cutLine(g, a.hr, a.or, yc, true, 1); }
  else { cutLine(g, a.hl, a.ol, yc, false, 1); cutLine(g, a.or, a.hr, yc, false, 1); }
}

/* ── label placement ──────────────────────────────────────── */
function lowerLabelPos(hp, yc) {
  var a = anchorsAt(yc + 9, hp);
  if (!a) return [CX - 40, yc + 72];
  var x = (a.ol + a.hl) / 2;
  x = Math.min(x, a.hl - 28);
  x = Math.max(x, a.ol + 28);
  return [x, yc + 72];
}
function upperLabelPos(yc) {
  return [196, Math.min(196, yc - 66)];
}

/* ── body (region + boundary + arrows) ────────────────────── */
function drawBody(t, hp, opt) {
  var reg = t.path(pathStr(OUTER) + ' ' + pathStr(hp)).attr({ 'fill-rule': 'evenodd' }).fill(COL.fill).stroke('none');
  interact(reg, 'R — the shaded, doubly connected region', 'The region R',
    'R lies between the outer curve C₁ and the hole boundary C₂. It is not simply connected, so Green\'s Theorem cannot be applied to it directly.');

  var hole = t.path(pathStr(hp)).fill('#ffffff').stroke('none');
  hole.css('cursor', 'move');
  hole.on('mousemove', function (e) { showTooltip('Drag me — the cuts follow', e); });
  hole.on('mouseleave', function () { hideTooltip(); });
  hole.on('pointerdown', function (e) {
    e.preventDefault();
    var p = toLocal(e, opt.ox, opt.oy);
    dragCtx = { ox: opt.ox, oy: opt.oy, dx: figState.hx - p[0], dy: figState.hy - p[1] };
  });

  var oc = t.path(pathStr(OUTER)).fill('none').stroke({ color: COL.blue, width: 8, linejoin: 'round' });
  interact(oc, 'C₁ — outer boundary, counterclockwise', 'Outer curve C₁',
    'Travelling counterclockwise along C₁ keeps the shaded region on your left. That is the positive orientation for the outer boundary.');
  var hc = t.path(pathStr(hp)).fill('none').stroke({ color: COL.blue, width: 8, linejoin: 'round' });
  interact(hc, 'C₂ — hole boundary, clockwise', 'Hole boundary C₂',
    'The hole boundary must be traversed clockwise. It looks "backwards", but it obeys exactly the same rule: the region R stays on your left as you walk.');

  curveArrow(t, outerPt, 1.95, 1, 38, 30, COL.blue);
  curveArrow(t, outerPt, -0.75, 1, 38, 30, COL.blue);
  curveArrow(t, holePt, 0.85, -1, 30, 25, COL.blue);
  curveArrow(t, holePt, -1.45, -1, 30, 25, COL.blue);
  curveArrow(t, holePt, -2.55, -1, 30, 25, COL.blue);

  if (figState.walk) addWalkers(t);
}
function addWalkers(t) {
  var g = t.group();
  [{ f: outerPt, s: 1, t0: 0.4 }, { f: holePt, s: -1, t0: 1.6 }].forEach(function (w) {
    var line = g.line(0, 0, 0, 0).stroke({ color: COL.accent, width: 4 });
    var nrm = g.polygon([[0, 0], [1, 0], [1, 1]]).fill(COL.accent);
    var dot = g.circle(15).fill('#ffffff').stroke({ color: COL.accent, width: 4 }).center(-99, -99);
    walkers.push({ f: w.f, s: w.s, t0: w.t0, dot: dot, line: line, nrm: nrm });
  });
}

/* ── panels ───────────────────────────────────────────────── */
function drawPanel(ox, oy, opt) {
  var g = gfxDraw.group().translate(ox, oy);
  if (opt.dim) g.opacity(0.28);
  var hp = holePts(), yc = cutY(), st = opt.stage, sep = 20;
  opt.ox = ox; opt.oy = oy;
  var up = upperLabelPos(yc), lp = lowerLabelPos(hp, yc);
  var c2x = figState.hx - 38, c2y = figState.hy - HRY * figState.hs - 30;

  if (st === 2) {
    var wrapU = g.group().translate(0, -sep);
    var inU = wrapU.group();
    var cpU = gfxDraw.clip(); cpU.add(gfxDraw.rect(PW + 260, yc + 520).move(-130, -520));
    inU.clipWith(cpU);
    drawBody(inU, hp, opt);
    drawCutEdges(wrapU.group(), yc, hp, true);
    mathSub(wrapU, c2x, c2y, 'C', '2', 38);
    txt(wrapU, up[0], up[1], 'R\u2032', 40, 'middle', COL.ink, true, true);

    var wrapL = g.group().translate(0, sep);
    var inL = wrapL.group();
    var cpL = gfxDraw.clip(); cpL.add(gfxDraw.rect(PW + 260, 900).move(-130, yc));
    inL.clipWith(cpL);
    drawBody(inL, hp, opt);
    drawCutEdges(wrapL.group(), yc, hp, false);
    txt(wrapL, lp[0], lp[1], 'R\u2033', 40, 'middle', COL.ink, true, true);
  } else {
    drawBody(g, hp, opt);
    if (st >= 1) drawCutBands(g, yc, hp, st === 3);
    mathSub(g, c2x, c2y, 'C', '2', 38);
    if (st === 0) {
      txt(g, 200, 196, 'R', 40, 'middle', COL.ink, true, true);
    } else {
      txt(g, up[0], up[1], 'R\u2032', 40, 'middle', COL.ink, true, true);
      txt(g, lp[0], lp[1], 'R\u2033', 40, 'middle', COL.ink, true, true);
    }
  }

  mathSub(g, 250, 44, 'C', '1', 40);
  txt(g, 250, 545, opt.caption, 40, 'middle', COL.ink, true, false);

  if (opt.which === 'a' && figState.step === 1) {
    txt(g, 250, 500, 'positive orientation: region always on the left', 20, 'middle', COL.accent, false, true);
  }
  if (opt.which === 'b' && figState.step === 4) {
    txt(g, 250, 500, 'cut contributions cancel in pairs', 20, 'middle', COL.red, false, true);
  }
}

/* ── render / layout ──────────────────────────────────────── */
var panelA = [0, 0], panelB = [0, 0];
function render() {
  gfxDraw.clear();
  walkers = [];
  var w = figHost.clientWidth || 800, h = figHost.clientHeight || 600;
  var side = (w / Math.max(1, h)) > 1.55;   /* stacked, like the source, unless very wide */
  if (side) { gfxDraw.viewbox(0, 0, 1050, 600); panelA = [15, 18]; panelB = [545, 18]; }
  else { gfxDraw.viewbox(0, 0, 520, 1155); panelA = [10, 2]; panelB = [10, 582]; }
  var focus = STEPS[figState.step] ? STEPS[figState.step].focus : null;
  drawPanel(panelA[0], panelA[1], { stage: 0, caption: '(a)', which: 'a', dim: focus === 'b' });
  drawPanel(panelB[0], panelB[1], { stage: figState.stage, caption: '(b)', which: 'b', dim: focus === 'a' });
}

function toLocal(evt, ox, oy) {
  var pt = gfxDraw.node.createSVGPoint();
  pt.x = evt.clientX; pt.y = evt.clientY;
  var p = pt.matrixTransform(gfxDraw.node.getScreenCTM().inverse());
  return [p.x - ox, p.y - oy];
}
document.addEventListener('pointermove', function (e) {
  if (!dragCtx) return;
  var p = toLocal(e, dragCtx.ox, dragCtx.oy);
  tryHole(p[0] + dragCtx.dx, p[1] + dragCtx.dy, figState.hs);
});
document.addEventListener('pointerup', function () { dragCtx = null; });

/* ── animation ────────────────────────────────────────────── */
var uPhase = 0;
function tick() {
  if (figState.walk && walkers.length) {
    uPhase += 0.0022; if (uPhase > 1) uPhase -= 1;
    for (var i = 0; i < walkers.length; i++) {
      var wk = walkers[i], tt = wk.t0 + wk.s * uPhase * 2 * Math.PI;
      var p = wk.f(tt), p1 = wk.f(tt + 0.02 * wk.s), p0 = wk.f(tt - 0.02 * wk.s);
      var dx = p1[0] - p0[0], dy = p1[1] - p0[1], m = Math.sqrt(dx * dx + dy * dy) || 1;
      var ux = dx / m, uy = dy / m, lx = uy, ly = -ux;
      wk.dot.center(p[0], p[1]);
      wk.line.plot(p[0], p[1], p[0] + lx * 24, p[1] + ly * 24);
      wk.nrm.plot(triPts(p[0] + lx * 31, p[1] + ly * 31, lx, ly, 14, 12));
    }
  }
  requestAnimationFrame(tick);
}

/* ── controls ─────────────────────────────────────────────── */
function setStage(i) { figState.stage = i; updateStageButtons(); render(); }
function updateStageButtons() {
  for (var i = 0; i < 4; i++) {
    var el = document.getElementById('stageBtn' + i);
    if (el) el.classList.toggle('active', i === figState.stage);
  }
}
function toggle_traverseArrow(on) { figState.walk = !!on; render(); }
function update_holeSize(v) { tryHole(figState.hx, figState.hy, v); }
function resetHole() {
  figState.hx = HX0; figState.hy = HY0; figState.hs = 1;
  document.getElementById('holeSizeInput').value = 1;
  document.getElementById('holeSizeVal').value = '1.00';
  render();
}

/* ── demo steps ───────────────────────────────────────────── */
var STEPS = [
  {
    t: 'A doubly connected region', stage: 1, walk: false, focus: null,
    n: 'The shaded region R lies between an outer curve C₁ and the boundary C₂ of a hole. Because of the hole, R is not simply connected, so Green\'s Theorem does not apply directly.'
  },
  {
    t: 'Positive orientation means region on your left', stage: 1, walk: true, focus: 'a',
    n: 'Walk the boundary: on C₁ you travel counterclockwise, but on C₂ you must travel clockwise. In both cases the shaded region stays on your left (orange arrow) — that is the single rule behind the two apparently opposite directions.'
  },
  {
    t: 'Introduce two cuts', stage: 1, walk: false, focus: 'b',
    n: 'Two horizontal cuts are drawn from the outer curve to the hole. Each cut is a single segment, but it will be traversed once in each direction.'
  },
  {
    t: 'Two simply connected pieces', stage: 2, walk: false, focus: 'b',
    n: 'The cuts split R into an upper piece R′ and a lower piece R″. Each has no hole, so Green\'s Theorem applies to each separately; their boundaries include the cut segments.'
  },
  {
    t: 'The cuts cancel', stage: 3, walk: false, focus: 'b',
    n: 'Along each cut, R′ is traversed rightward while R″ is traversed leftward. The two line integrals are negatives of each other and cancel, leaving exactly the integral over C₁ counterclockwise plus C₂ clockwise.'
  }
];
function applyStep(i) {
  figState.step = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[figState.step];
  figState.stage = s.stage;
  figState.walk = s.walk;
  var cb = document.getElementById('traverseArrowInput');
  if (cb) cb.checked = s.walk;
  document.getElementById('demoNarration').innerHTML = '<b>' + s.t + '.</b> ' + s.n;
  document.getElementById('stepLabel').textContent = (figState.step + 1) + ' / ' + STEPS.length;
  updateStageButtons();
  render();
}
function nextStep() { applyStep(figState.step + 1); }
function prevStep() { applyStep(figState.step - 1); }

/* ── boot ─────────────────────────────────────────────────── */
document.addEventListener('fig-resize', function () { render(); });
applyStep(0);
requestAnimationFrame(tick);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Green's Theorem extends to a multiply connected region by cutting it into simply connected pieces: the cuts are traversed twice in opposite directions so their contributions cancel, leaving the outer boundary counterclockwise and the inner boundary clockwise.
KEY INSIGHT (what students should walk away understanding): The 'backwards' clockwise orientation of the hole is forced by one rule — keep the region on your left — and the cuts that prove it disappear because every cut is walked once in each direction.
DEMO STEPS: 5 guided steps — implement the step player in #ui

